import type { Lesson, Project } from '../../../types';

type TreeNode = { value: number; left: TreeNode | null; right: TreeNode | null };

/** A binary search tree built by inserting the values in the given order (used for the hidden test cases of a challenge). */
function bst(values: number[]): TreeNode | null {
  let root: TreeNode | null = null;
  for (const value of values) {
    if (root === null) {
      root = { value, left: null, right: null };
      continue;
    }
    let node: TreeNode = root;
    for (;;) {
      const side: 'left' | 'right' = value < node.value ? 'left' : 'right';
      const next: TreeNode | null = node[side];
      if (next === null) {
        node[side] = { value, left: null, right: null };
        break;
      }
      node = next;
    }
  }
  return root;
}

